  final _seen = <Object?>{};
  @override
  late B current;
  @override
  bool moveNext() {
    while (_it.moveNext()) {
      final v = _f(_it.current);
      if (_seen.add(v)) {
        current = v;
        return true;
      }
    }
    return false;
  }
}

