(List<A>, List<B>) unzip<A, B>(Iterable<(A, B)> iterable) {
  final lefts = <A>[];
  final rights = <B>[];
  if (iterable is List<(A, B)>) {
    final length = iterable.length;
    for (var i = 0; i < length; i++) {
      final (a, b) = iterable[i];
      lefts.add(a);
      rights.add(b);
    }
    return (lefts, rights);
  }
  for (final (a, b) in iterable) {
    lefts.add(a);
    rights.add(b);
  }
  return (lefts, rights);
}

