int _compareKeys(Object? fa, Object? fb) {
  if (fa is num && fb is num) {
    return fa.compareTo(fb);
  }
  if (fa is Comparable && fb is Comparable) {
    return Comparable.compare(
      fa as Comparable<Object?>,
      fb as Comparable<Object?>,
    );
  }
  return 0;
}

