  for (var width = 1; width < n; width <<= 1) {
    for (var lo = 0; lo < n; lo += width << 1) {
      var mid = lo + width;
      if (mid > n) mid = n;
      var hi = mid + width;
      if (hi > n) hi = n;
      var i = lo, j = mid, t = lo;
      while (i < mid && j < hi) {
        final a = srcK[i];
        final b = srcK[j];
        if (desc ? a.compareTo(b) >= 0 : a.compareTo(b) <= 0) {
          dstK[t] = a;
          dstV[t] = srcV[i];
          i++;
        } else {
          dstK[t] = b;
          dstV[t] = srcV[j];
          j++;
        }
        t++;
      }
      while (i < mid) {
        dstK[t] = srcK[i];
        dstV[t] = srcV[i];
        i++;
        t++;
      }
      while (j < hi) {
        dstK[t] = srcK[j];
        dstV[t] = srcV[j];
        j++;
        t++;
      }
    }
    final tk = srcK;
    srcK = dstK;
    dstK = tk;
    final tv = srcV;
    srcV = dstV;
    dstV = tv;
  }
  return srcV;
