List<A> _topByImpl<A>(
  int k,
  Object? Function(A a) f,
  Iterable<A> iterable,
  int sign,
) {
  final values = <A>[];
  if (k <= 0) return values;
  final keys = <Object?>[];
  if (iterable is List<A>) {
    final length = iterable.length;
    for (var i = 0; i < length; i++) {
      final a = iterable[i];
      _offerBoundary(values, keys, k, sign, a, f(a));
    }
  } else {
    for (final a in iterable) {
      _offerBoundary(values, keys, k, sign, a, f(a));
    }
  }
  return values;
}

void _offerBoundary<A>(
  List<A> values,
  List<Object?> keys,
  int k,
  int sign,
  A a,
  Object? key,
) {
  if (values.length < k) {
    values.add(a);
    keys.add(key);
  } else if (_compareKeys(key, keys[k - 1]) * sign <= 0) {
    return;
  }
  var i = values.length - 1;
  while (i > 0 && _compareKeys(keys[i - 1], key) * sign < 0) {
    keys[i] = keys[i - 1];
    values[i] = values[i - 1];
    i--;
  }
  keys[i] = key;
  values[i] = a;
}

Future<List<A>> topByAsync<A>(
  int k,
  Object? Function(A a) f,
  FxAsyncIterable<A> iterable,
) => _topByAsyncImpl(k, f, iterable, 1);

Future<List<A>> bottomByAsync<A>(
  int k,
  Object? Function(A a) f,
  FxAsyncIterable<A> iterable,
) => _topByAsyncImpl(k, f, iterable, -1);

Future<List<A>> _topByAsyncImpl<A>(
  int k,
  Object? Function(A a) f,
  FxAsyncIterable<A> iterable,
  int sign,
) async {
  final values = <A>[];
  if (k <= 0) return values;
  final keys = <Object?>[];
  await eachAsync(
    (A a) => _offerBoundary(values, keys, k, sign, a, f(a)),
    iterable,
  );
  return values;
}

@pragma('vm:prefer-inline')
(List<A>, List<A>) partition<A>(bool Function(A a) f, Iterable<A> iterable) {
  final pass = <A>[];
  final fail = <A>[];
  if (iterable is List<A>) {
    final length = iterable.length;
    for (var i = 0; i < length; i++) {
      final a = iterable[i];
      (f(a) ? pass : fail).add(a);
    }
    return (pass, fail);
  }
  for (final a in iterable) {
    (f(a) ? pass : fail).add(a);
  }
  return (pass, fail);
}

