  return (pass, fail);
}


typedef Fold<A, R> = ({R seed, R Function(R acc, A a) step});

@pragma('vm:align-loops')
(R1, R2) tee<A, R1, R2>(
  Iterable<A> iterable,
  Fold<A, R1> first,
  Fold<A, R2> second,
) {
  final f1 = first.step;
  final f2 = second.step;
  var a1 = first.seed;
  var a2 = second.seed;
  for (final a in iterable) {
    a1 = f1(a1, a);
    a2 = f2(a2, a);
  }
  return (a1, a2);
}

@pragma('vm:align-loops')
(R1, R2, R3) tee3<A, R1, R2, R3>(
  Iterable<A> iterable,
  Fold<A, R1> first,
  Fold<A, R2> second,
  Fold<A, R3> third,
) {
  final f1 = first.step;
  final f2 = second.step;
  final f3 = third.step;
  var a1 = first.seed;
  var a2 = second.seed;
  var a3 = third.seed;
  for (final a in iterable) {
    a1 = f1(a1, a);
    a2 = f2(a2, a);
    a3 = f3(a3, a);
  }
  return (a1, a2, a3);
}

Future<(R1, R2)> teeAsync<A, R1, R2>(
  FxAsyncIterable<A> iterable,
  AsyncFold<A, R1> first,
  AsyncFold<A, R2> second,
) async {
  final f1 = first.step;
  final f2 = second.step;
  var a1 = await first.seed;
  var a2 = await second.seed;
  await eachAsync((A a) {
    final r1 = f1(a1, a);
    if (r1 is Future<R1>) {
      return r1.then((v1) {
        a1 = v1;
        final r2 = f2(a2, a);
        if (r2 is Future<R2>) return r2.then((v2) => a2 = v2);
        a2 = r2;
      });
    }
    a1 = r1;
    final r2 = f2(a2, a);
    if (r2 is Future<R2>) return r2.then((v2) => a2 = v2);
    a2 = r2;
  }, iterable);
  return (a1, a2);
}

