Either<NonEmptyList<E>, List<R>> mapOrAccumulate<E, T, R>(
  R Function(AccumulatingRaise<E> r, T item) transform,
  Iterable<T> iterable,
) => either<NonEmptyList<E>, List<R>>(
  (r) => r.mapOrAccumulate(iterable, transform),
