Future<Either<NonEmptyList<E>, List<R>>> mapOrAccumulateAsync<E, T, R>(
  FutureOr<R> Function(AccumulatingRaise<E> r, T item) transform,
  FxAsyncIterable<T> iterable, {
  int? concurrency,
}) async {
  var mapped = FxAsync(iterable).map(
    (item) => eitherAsync<NonEmptyList<E>, R>(
      (r) => transform(AccumulatingRaise.over(r), item),
    ),
  );
  if (concurrency != null) mapped = mapped.concurrent(concurrency);
  final errors = <E>[];
  final results = <R>[];
  await mapped.each((e) {
    switch (e) {
      case Left(:final value):
        errors.addAll(value);
      case Right(:final value):
        if (errors.isEmpty) results.add(value);
    }
  });
  return errors.isEmpty ? Right(results) : Left(NonEmptyList.orNull(errors)!);
}

extension FxEitherOps<L, R> on Fx<Either<L, R>> {
  List<R> rights() => [
    for (final e in this)
      if (e case Right(:final value)) value,
  ];

  List<L> lefts() => [
    for (final e in this)
      if (e case Left(:final value)) value,
  ];

  (List<L>, List<R>) separated() => separateEither(this);

  Either<L, List<R>> sequence() => sequenceEither(this);

  EitherNel<L, List<R>> flattenOrAccumulate() =>
      either<NonEmptyList<L>, List<R>>(
        (r) => r.mapOrAccumulate(this, (br, Either<L, R> e) => br.bind(e)),
      );
}

extension FxAsyncEitherOps<L, R> on FxAsync<Either<L, R>> {
  Future<Either<L, List<R>>> sequence() => sequenceEitherAsync(this);

  Future<List<R>> rights() => rightsAsync(this);

  Future<List<L>> lefts() => leftsAsync(this);

  Future<(List<L>, List<R>)> separated() => separateEitherAsync(this);

  Future<EitherNel<L, List<R>>> flattenOrAccumulate() =>
      flattenOrAccumulateAsync(this);
}

extension FxAccumulateOps<T> on Fx<T> {
  Either<NonEmptyList<E>, List<R>> mapOrAccumulate<E, R>(
    R Function(AccumulatingRaise<E> r, T item) transform,
  ) => either<NonEmptyList<E>, List<R>>(
    (r) => r.mapOrAccumulate(this, transform),
  );
}

extension FxAsyncAccumulateOps<T> on FxAsync<T> {
  Future<Either<NonEmptyList<E>, List<R>>> mapOrAccumulate<E, R>(
    FutureOr<R> Function(AccumulatingRaise<E> r, T item) transform, {
    int? concurrency,
  }) => mapOrAccumulateAsync(transform, this, concurrency: concurrency);
}



FxEvents<T> fxEvents<T>(Stream<T> stream) => FxEvents(stream);

class FxEvents<T> {
  final Stream<T> _inner;

  const FxEvents(this._inner);

  Stream<T> get stream => _inner;

  static FxEvents<T> race<T>(Iterable<Stream<T>> candidates) {
    final list = List.of(candidates);
    final out = StreamController<T>();
    final subs = <StreamSubscription<T>>[];
    var done = 0;
    var winner = -1;

    void claim(int i, void Function() deliver) {
      if (winner == -1) {
        winner = i;
        for (var j = 0; j < subs.length; j++) {
          if (j != i) subs[j].cancel();
        }
      }
      if (winner == i) deliver();
    }

    out.onListen = () {
      if (list.isEmpty) {
        out.close();
        return;
      }
      for (var i = 0; i < list.length; i++) {
        subs.add(
          list[i].listen(
            (v) => claim(i, () => out.add(v)),
            onError: (Object e, StackTrace st) =>
                claim(i, () => out.addError(e, st)),
            onDone: () {
              if (winner == i) {
                out.close();
              } else if (winner == -1 && ++done == list.length) {
                out.close();
              }
            },
          ),
        );
      }
      out.onCancel = () => Future.wait(subs.map((s) => s.cancel()));
    };
    return FxEvents(out.stream);
  }

  static FxEvents<T> merge<T>(Iterable<Stream<T>> sources) {
    final list = List.of(sources);
    final out = StreamController<T>();
    final subs = <StreamSubscription<T>>[];
    var done = 0;
    out.onListen = () {
      if (list.isEmpty) {
        out.close();
        return;
      }
      for (final s in list) {
        subs.add(
          s.listen(
            out.add,
            onError: out.addError,
            onDone: () {
              if (++done == list.length) out.close();
            },
          ),
        );
      }
      out.onCancel = () => Future.wait(subs.map((s) => s.cancel()));
    };
    return FxEvents(out.stream);
  }

  static FxEvents<T> concat<T>(Iterable<Stream<T>> sources) =>
      FxEvents(_concat(sources));

  static Stream<T> _concat<T>(Iterable<Stream<T>> sources) async* {
    for (final source in sources) {
      yield* source;
    }
  }

  static FxEvents<R> zip<T, R>(
    Iterable<Stream<T>> sources,
    R Function(List<T> values) combine,
  ) {
    final list = List.of(sources);
    final out = StreamController<R>();
    final subs = <StreamSubscription<T>>[];
    out.onListen = () {
      if (list.isEmpty) {
        out.close();
        return;
      }
      final buffers = [for (var i = 0; i < list.length; i++) <T>[]];
      final closed = List.filled(list.length, false);

      void pump() {
        if (out.isClosed) return;
        while (buffers.every((b) => b.isNotEmpty)) {
          out.add(combine([for (final b in buffers) b.removeAt(0)]));
        }
        for (var i = 0; i < list.length; i++) {
          if (closed[i] && buffers[i].isEmpty) {
            out.close();
            return;
          }
        }
      }

      for (var i = 0; i < list.length; i++) {
        final index = i;
        subs.add(
          list[i].listen(
            (v) {
              buffers[index].add(v);
              pump();
            },
            onError: out.addError,
            onDone: () {
              closed[index] = true;
              pump();
            },
          ),
        );
      }
      out.onCancel = () => Future.wait(subs.map((s) => s.cancel()));
    };
    return FxEvents(out.stream);
  }

  static FxEvents<List<T>> combineLatestAll<T>(Iterable<Stream<T>> sources) {
    final list = List.of(sources);
    final out = StreamController<List<T>>();
    final subs = <StreamSubscription<T>>[];
    out.onListen = () {
      if (list.isEmpty) {
        out.close();
        return;
      }
      final latest = List<T?>.filled(list.length, null);
      final has = List.filled(list.length, false);
      var seen = 0;
      var done = 0;

      for (var i = 0; i < list.length; i++) {
        final index = i;
        subs.add(
          list[i].listen(
            (v) {
              if (!has[index]) {
                has[index] = true;
                seen++;
              }
              latest[index] = v;
              if (seen == list.length) {
                out.add([for (final v in latest) v as T]);
              }
            },
            onError: out.addError,
            onDone: () {
              if (++done == list.length) out.close();
            },
          ),
        );
      }
      out.onCancel = () => Future.wait(subs.map((s) => s.cancel()));
    };
    return FxEvents(out.stream);
  }

  static FxEvents<List<T>> waitAll<T>(Iterable<Stream<T>> sources) {
    final list = List.of(sources);
    final out = StreamController<List<T>>();
    final subs = <StreamSubscription<T>>[];
    out.onListen = () {
      if (list.isEmpty) {
        out
          ..add(<T>[])
          ..close();
        return;
      }
      final last = List<T?>.filled(list.length, null);
      final has = List.filled(list.length, false);
      var done = 0;

      for (var i = 0; i < list.length; i++) {
        final index = i;
        subs.add(
          list[i].listen(
            (v) {
              last[index] = v;
              has[index] = true;
            },
            onError: out.addError,
            onDone: () {
              if (++done == list.length) {
                if (!has.contains(false)) {
                  out.add([for (final v in last) v as T]);
                }
                out.close();
              }
            },
          ),
        );
      }
      out.onCancel = () => Future.wait(subs.map((s) => s.cancel()));
    };
    return FxEvents(out.stream);
  }

  static FxEvents<T> retry<T>(Stream<T> Function() factory, [int? count]) {
    final out = StreamController<T>();
    out.onListen = () {
      var retries = 0;
      StreamSubscription<T>? sub;

      void attempt() {
        final Stream<T> source;
        try {
          source = factory();
        } catch (e, st) {
          out
            ..addError(e, st)
            ..close();
          return;
        }
        sub = source.listen(
          out.add,
          onError: (Object e, StackTrace st) {
            sub!.cancel();
            sub = null;
            if (count != null && retries >= count) {
              out
                ..addError(e, st)
                ..close();
              return;
            }
            retries++;
            attempt();
          },
          onDone: out.close,
        );
      }

      attempt();
      out.onCancel = () => sub?.cancel();
    };
    return FxEvents(out.stream);
  }


  FxEvents<T> stopOn(Stream<void> trigger) {
    final out = StreamController<T>();
    out.onListen = () {
      late final StreamSubscription<T> sourceSub;
      late final StreamSubscription<void> triggerSub;
      sourceSub = _inner.listen(
        out.add,
        onError: out.addError,
        onDone: () {
          triggerSub.cancel();
          out.close();
        },
      );
      triggerSub = trigger.listen((_) {
        sourceSub.cancel();
        triggerSub.cancel();
        out.close();
      }, onError: out.addError);
      out.onCancel = () =>
          Future.wait([sourceSub.cancel(), triggerSub.cancel()]);
    };
    return FxEvents(out.stream);
  }

  FxEvents<T> startOn(Stream<void> trigger) {
    final out = StreamController<T>();
    out.onListen = () {
      var open = false;
      late final StreamSubscription<T> sourceSub;
      late final StreamSubscription<void> triggerSub;
      sourceSub = _inner.listen(
        (v) {
          if (open) out.add(v);
        },
        onError: out.addError,
        onDone: () {
          triggerSub.cancel();
          out.close();
        },
      );
      triggerSub = trigger.listen((_) {
        open = true;
        triggerSub.cancel();
      }, onError: out.addError);
      out.onCancel = () =>
          Future.wait([sourceSub.cancel(), triggerSub.cancel()]);
    };
    return FxEvents(out.stream);
  }


  FxEvents<T> debounce(Duration window) {
    final out = StreamController<T>();
    out.onListen = () {
      Timer? timer;
      late T pending;
      var hasPending = false;
      final sub = _inner.listen(
        (v) {
          pending = v;
          hasPending = true;
          timer?.cancel();
          timer = Timer(window, () {
            hasPending = false;
            out.add(pending);
          });
        },
        onError: out.addError,
        onDone: () {
          timer?.cancel();
          if (hasPending) out.add(pending);
          out.close();
        },
      );
      out
        ..onPause = sub.pause
        ..onResume = sub.resume
        ..onCancel = () {
          timer?.cancel();
          return sub.cancel();
        };
    };
    return FxEvents(out.stream);
  }

  FxEvents<T> throttle(
    Duration window, {
    bool leading = true,
    bool trailing = false,
  }) {
    final out = StreamController<T>();
    out.onListen = () {
      Timer? timer;
      late T pending;
      var hasPending = false;
      var closed = false;

      void endWindow() {
        timer = null;
        if (trailing && hasPending) {
          hasPending = false;
          out.add(pending);
        }
        if (closed) out.close();
      }

      final sub = _inner.listen(
        (v) {
          if (timer == null) {
            timer = Timer(window, endWindow);
            if (leading) {
              out.add(v);
              return;
            }
          }
          pending = v;
          hasPending = trailing;
        },
        onError: out.addError,
        onDone: () {
          closed = true;
          if (timer == null || !(trailing && hasPending)) {
            timer?.cancel();
            out.close();
          }
        },
      );
      out
        ..onPause = sub.pause
        ..onResume = sub.resume
        ..onCancel = () {
          timer?.cancel();
          return sub.cancel();
        };
    };
    return FxEvents(out.stream);
  }

  FxEvents<T> sampleOn(Stream<void> trigger) {
    final out = StreamController<T>();
    out.onListen = () {
      late T latest;
      var hasNew = false;
      late final StreamSubscription<T> sourceSub;
      late final StreamSubscription<void> triggerSub;
      sourceSub = _inner.listen(
        (v) {
          latest = v;
          hasNew = true;
        },
        onError: out.addError,
        onDone: () {
          triggerSub.cancel();
          out.close();
        },
      );
      triggerSub = trigger.listen((_) {
        if (hasNew) {
          hasNew = false;
          out.add(latest);
        }
      }, onError: out.addError);
      out.onCancel = () =>
          Future.wait([sourceSub.cancel(), triggerSub.cancel()]);
    };
    return FxEvents(out.stream);
  }

  FxEvents<T> sample(Duration period) =>
      sampleOn(Stream<int>.periodic(period, (i) => i));

  FxEvents<T> delay(Duration duration) {
    final out = StreamController<T>();
    out.onListen = () {
      final timers = <Timer>{};
      var closed = false;
      void settle() {
        if (closed && timers.isEmpty) out.close();
      }

      final sub = _inner.listen(
        (v) {
          late final Timer timer;
          timer = Timer(duration, () {
            timers.remove(timer);
            out.add(v);
            settle();
          });
          timers.add(timer);
        },
        onError: out.addError,
        onDone: () {
          closed = true;
          settle();
        },
      );
      out.onCancel = () {
        for (final t in timers) {
          t.cancel();
        }
        timers.clear();
        return sub.cancel();
      };
    };
    return FxEvents(out.stream);
  }

  FxEvents<T> spaceBy(Duration gap) {
    final out = StreamController<T>();
    out.onListen = () {
      final queue = <T>[];
      Timer? timer;
      var closed = false;
      void settle() {
        if (closed && queue.isEmpty && timer == null) out.close();
      }

      void pump() {
        timer = Timer(gap, () {
          timer = null;
          if (queue.isNotEmpty) {
            out.add(queue.removeAt(0));
            if (queue.isNotEmpty) pump();
          }
          settle();
        });
      }

      final sub = _inner.listen(
        (v) {
          queue.add(v);
          if (timer == null) pump();
        },
        onError: out.addError,
        onDone: () {
          closed = true;
          settle();
        },
      );
      out.onCancel = () {
        timer?.cancel();
        return sub.cancel();
      };
    };
    return FxEvents(out.stream);
  }


  FxEvents<List<T>> chunk(int count) {
    if (count < 1) {
      throw ArgumentError.value(count, 'count', 'must be at least 1');
    }
    final out = StreamController<List<T>>();
    out.onListen = () {
      var batch = <T>[];
      final sub = _inner.listen(
        (v) {
          batch.add(v);
          if (batch.length == count) {
            out.add(batch);
            batch = <T>[];
          }
        },
        onError: out.addError,
        onDone: () {
          if (batch.isNotEmpty) out.add(batch);
          out.close();
        },
      );
      out
        ..onPause = sub.pause
        ..onResume = sub.resume
        ..onCancel = sub.cancel;
    };
    return FxEvents(out.stream);
  }

  FxEvents<List<T>> chunkOn(Stream<void> trigger) {
    final out = StreamController<List<T>>();
    out.onListen = () {
      var batch = <T>[];
      late final StreamSubscription<T> sourceSub;
      late final StreamSubscription<void> triggerSub;
      sourceSub = _inner.listen(
        (v) => batch.add(v),
        onError: out.addError,
        onDone: () {
          triggerSub.cancel();
          if (batch.isNotEmpty) out.add(batch);
          out.close();
        },
      );
      triggerSub = trigger.listen((_) {
        if (batch.isNotEmpty) {
          out.add(batch);
          batch = <T>[];
        }
      }, onError: out.addError);
      out.onCancel = () =>
          Future.wait([sourceSub.cancel(), triggerSub.cancel()]);
    };
    return FxEvents(out.stream);
  }

  FxEvents<List<T>> chunkEvery(Duration window) {
    final out = StreamController<List<T>>();
    out.onListen = () {
      var batch = <T>[];
      void flush() {
        if (batch.isNotEmpty) {
          out.add(batch);
          batch = <T>[];
        }
      }

      final timer = Timer.periodic(window, (_) => flush());
      final sub = _inner.listen(
        (v) => batch.add(v),
        onError: out.addError,
        onDone: () {
          timer.cancel();
          flush();
          out.close();
        },
      );
      out
        ..onPause = sub.pause
        ..onResume = sub.resume
        ..onCancel = () {
          timer.cancel();
          return sub.cancel();
        };
    };
    return FxEvents(out.stream);
  }


  FxEvents<R> combineLatest<U, R>(
    Stream<U> other,
    R Function(T a, U b) combine,
  ) {
    final out = StreamController<R>();
    out.onListen = () {
      late T a;
      late U b;
      var hasA = false, hasB = false;
      var done = 0;
      void emit() {
        if (hasA && hasB) out.add(combine(a, b));
      }

      void onDone() {
        if (++done == 2) out.close();
      }

      final subA = _inner.listen(
        (v) {
          a = v;
          hasA = true;
          emit();
        },
        onError: out.addError,
        onDone: onDone,
      );
      final subB = other.listen(
        (v) {
          b = v;
          hasB = true;
          emit();
        },
        onError: out.addError,
        onDone: onDone,
      );
      out.onCancel = () => Future.wait([subA.cancel(), subB.cancel()]);
    };
    return FxEvents(out.stream);
  }

  FxEvents<R> withLatestFrom<U, R>(
    Stream<U> other,
    R Function(T a, U b) combine,
  ) {
    final out = StreamController<R>();
    out.onListen = () {
      late U latest;
      var hasLatest = false;
      final otherSub = other.listen((v) {
        latest = v;
        hasLatest = true;
      }, onError: out.addError);
      late final StreamSubscription<T> sourceSub;
      sourceSub = _inner.listen(
        (v) {
          if (hasLatest) out.add(combine(v, latest));
        },
        onError: out.addError,
        onDone: () {
          otherSub.cancel();
          out.close();
        },
      );
      out.onCancel = () => Future.wait([sourceSub.cancel(), otherSub.cancel()]);
    };
    return FxEvents(out.stream);
  }

  FxEvents<R> zipWith<U, R>(Stream<U> other, R Function(T a, U b) combine) {
    final out = StreamController<R>();
    out.onListen = () {
      final bufferA = <T>[];
      final bufferB = <U>[];
      var closedA = false, closedB = false;

      void pump() {
        if (out.isClosed) return;
        while (bufferA.isNotEmpty && bufferB.isNotEmpty) {
          out.add(combine(bufferA.removeAt(0), bufferB.removeAt(0)));
        }
        if ((closedA && bufferA.isEmpty) || (closedB && bufferB.isEmpty)) {
          out.close();
        }
      }

      final subA = _inner.listen(
        (v) {
          bufferA.add(v);
          pump();
        },
        onError: out.addError,
        onDone: () {
          closedA = true;
          pump();
        },
      );
      final subB = other.listen(
        (v) {
          bufferB.add(v);
          pump();
        },
        onError: out.addError,
        onDone: () {
          closedB = true;
          pump();
        },
      );
      out.onCancel = () => Future.wait([subA.cancel(), subB.cancel()]);
    };
    return FxEvents(out.stream);
  }

  FxEvents<T> mergeWith(Stream<T> other) => FxEvents.merge([_inner, other]);

  FxEvents<T> raceWith(Stream<T> other) => FxEvents.race([_inner, other]);

  FxEvents<T> followedBy(Stream<T> next) => FxEvents.concat([_inner, next]);


  FxEvents<R> switchMap<R>(Stream<R> Function(T a) f) {
    final out = StreamController<R>();
    out.onListen = () {
      StreamSubscription<R>? innerSub;
      var outerDone = false;
      final sub = _inner.listen(
        (v) {
          innerSub?.cancel();
          final Stream<R> inner;
          try {
            inner = f(v);
          } catch (e, st) {
            out.addError(e, st);
            return;
          }
          late final StreamSubscription<R> s;
          s = inner.listen(
            out.add,
            onError: out.addError,
            onDone: () {
              if (identical(innerSub, s)) {
                innerSub = null;
                if (outerDone) out.close();
              }
            },
          );
          innerSub = s;
        },
        onError: out.addError,
        onDone: () {
          outerDone = true;
          if (innerSub == null) out.close();
        },
      );
      out.onCancel = () =>
          Future.wait([sub.cancel(), if (innerSub != null) innerSub!.cancel()]);
    };
    return FxEvents(out.stream);
  }

  FxEvents<R> mergeMap<R>(Stream<R> Function(T a) f, {int? concurrent}) {
    if (concurrent != null && concurrent < 1) {
      throw ArgumentError.value(concurrent, 'concurrent', 'must be at least 1');
    }
    final out = StreamController<R>();
    out.onListen = () {
      final inners = <StreamSubscription<R>>[];
      final waiting = <T>[];
      var outerDone = false;
      void settle() {
        if (outerDone && inners.isEmpty && waiting.isEmpty) out.close();
      }

      void start(T v) {
        final Stream<R> inner;
        try {
          inner = f(v);
        } catch (e, st) {
          out.addError(e, st);
          settle();
          return;
        }
        late final StreamSubscription<R> s;
        s = inner.listen(
          out.add,
          onError: out.addError,
          onDone: () {
            inners.remove(s);
            if (waiting.isNotEmpty) start(waiting.removeAt(0));
            settle();
          },
        );
        inners.add(s);
      }

      final sub = _inner.listen(
        (v) {
          if (concurrent != null && inners.length >= concurrent) {
            waiting.add(v);
          } else {
            start(v);
          }
        },
        onError: out.addError,
        onDone: () {
          outerDone = true;
          settle();
        },
      );
      out.onCancel = () =>
          Future.wait([sub.cancel(), for (final s in inners) s.cancel()]);
    };
    return FxEvents(out.stream);
  }

  FxEvents<R> concatMap<R>(Stream<R> Function(T a) f) =>
      FxEvents(_inner.asyncExpand(f));

  FxEvents<R> exhaustMap<R>(Stream<R> Function(T a) f) {
    final out = StreamController<R>();
    out.onListen = () {
      StreamSubscription<R>? innerSub;
      var outerDone = false;
      final sub = _inner.listen(
        (v) {
          if (innerSub != null) return;
          final Stream<R> inner;
          try {
            inner = f(v);
          } catch (e, st) {
            out.addError(e, st);
            return;
          }
          innerSub = inner.listen(
            out.add,
            onError: out.addError,
            onDone: () {
              innerSub = null;
              if (outerDone) out.close();
            },
          );
        },
        onError: out.addError,
        onDone: () {
          outerDone = true;
          if (innerSub == null) out.close();
        },
      );
