      late B prevKey;
      final sub = _inner.listen(
        (v) {
          final B key;
          try {
            key = f(v);
          } catch (e, st) {
            out.addError(e, st);
            return;
          }
          final keep = !hasPrev || key != prevKey;
          prevKey = key;
          hasPrev = true;
          if (keep) out.add(v);
        },
        onError: out.addError,
        onDone: out.close,
      );
      out
        ..onPause = sub.pause
        ..onResume = sub.resume
        ..onCancel = sub.cancel;
    };
    return FxEvents(out.stream);
  }

