}

class LiveValue<T> {
  final _controller = StreamController<T>.broadcast();
  T? _value;
  var _hasValue = false;
  var _closed = false;
  StreamSubscription<T>? _source;

  LiveValue();

  LiveValue.seeded(T value) : _value = value, _hasValue = true;

  LiveValue.from(Stream<T> source) {
    _bind(source);
  }

  LiveValue.seededFrom(T seed, Stream<T> source)
    : _value = seed,
      _hasValue = true {
    _bind(source);
  }

  void _bind(Stream<T> source) {
    _source = source.listen(
      (v) {
        _value = v;
        _hasValue = true;
        _controller.add(v);
      },
      onError: _controller.addError,
      onDone: close,
    );
  }

  bool get hasValue => _hasValue;

  T get value {
    if (!_hasValue) {
      throw StateError(
        'LiveValue has no value yet — check hasValue or use LiveValue.seeded',
      );
    }
    return _value as T;
  }

  bool get isClosed => _closed;

  void add(T value) {
    if (_closed) throw StateError('LiveValue is closed');
    _value = value;
    _hasValue = true;
    _controller.add(value);
  }

  FxEvents<T> get live {
    late StreamController<T> c;
    StreamSubscription<T>? sub;
    c = StreamController<T>(
      onListen: () {
        if (_hasValue) c.add(_value as T);
        if (_closed) {
          c.close();
          return;
        }
        sub = _controller.stream.listen(
          c.add,
          onError: c.addError,
          onDone: c.close,
        );
      },
      onPause: () => sub?.pause(),
      onResume: () => sub?.resume(),
      onCancel: () => sub?.cancel(),
    );
    return FxEvents(c.stream);
  }

  Stream<T> get stream => live.stream;

  Future<void> close() {
    _closed = true;
    final source = _source;
    _source = null;
    return Future.wait([
      if (source != null) source.cancel(),
      _controller.close(),
    ]);
  }
}


class FxSubscriptions {
  final _subs = <StreamSubscription<void>>[];

  int get length => _subs.length;

  bool get isEmpty => _subs.isEmpty;

  bool get isNotEmpty => _subs.isNotEmpty;

  StreamSubscription<T> add<T>(StreamSubscription<T> subscription) {
    _subs.add(subscription);
    return subscription;
  }

  void addAll(Iterable<StreamSubscription<void>> subscriptions) =>
      _subs.addAll(subscriptions);

  Future<void> cancelAll() {
    final pending = List.of(_subs);
    _subs.clear();
    return Future.wait(pending.map((s) => s.cancel()));
  }

  void pauseAll() {
    for (final s in _subs) {
      s.pause();
    }
  }

  void resumeAll() {
    for (final s in _subs) {
      s.resume();
    }
  }
}



