  static Either<L, R> catchingWith<L, R>(
    L Function(Object error, StackTrace stackTrace) onError,
    R Function() block,
  ) => _$typedCatching<Either<L, R>>(
    () => Right(block()),
    (error, stackTrace) => Left(onError(error, stackTrace)),
